#include <vector>

void demonstrate_proxy() {
    std::vector<bool> v = {false, true};

    // 1. Assignment using proxy's operator=
    v[0] = v[1]; // Sets bit 0 to value of bit 1

    // 2. Member function call on proxy
    v[0].flip(); // Requires the proxy object

    // 3. Implicit conversion to bool
    bool value = v[0]; // Calls proxy::operator bool()

    // DANGER: Cannot reliably store a reference to the element
    // std::vector<bool>::reference& illegal_ref = v[0]; 
}
